  let prev = null
  let allowed = 0
  let denied = 0

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') {
        throw new Fail(`unknown directive ${d}`)
      }
      if (d !== 'event' && started) throw new Fail('declarations must come before the first event')
      if (d === 'bucket') {
