        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const c = num('capacity', f[2], 1)
        const r = num('refill', f[3], 0)
        const p = num('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], makeBucket(f[1], c, r, p))
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const l = num('limit', f[2], 0)
        const s = num('span', f[3], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], makeWindow(f[1], l, s))
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!WORD.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const n of f.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        }
        routes.set(f[1], f.slice(2).map((n) => policies.get(n)))
      } else {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', f[1], 0)
        const key = f[2]
        if (!WORD.test(key)) throw new Fail(`invalid key ${key}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${f[1]} is before tick ${prev}`)
        started = true
        prev = tick
        let best = null
        for (const p of routes.keys()) {
          if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        }
        let denier = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            const k = p.name + '\0' + key
            if (!states.has(k)) states.set(k, p.fresh())
            return states.get(k)
