          }
          if (denier === null) list.forEach((p, j) => p.record(sts[j], tick))
        }
        const st = stats.get(key) ?? { a: 0, d: 0 }
        stats.set(key, st)
        if (denier === null) { st.a++; allowed++; out.push(`${f[1]} ${key} allow`) }
        else { st.d++; denied++; out.push(`${f[1]} ${key} deny ${denier}`) }
