      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'summary') {
    const o = []
    for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      o.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
